 "model": {
  "variables": [
   {
    "name": "steaks eaten",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "chicken breasts eaten",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "steaks eaten",
     "coef": 900.0
    },
    {
     "var": "chicken breasts eaten",
     "coef": 700.0
    }
   ]
  },
  "constraints": [
   {
    "name": "chicken at least twice steaks",
    "terms": [
     {
      "var": "chicken breasts eaten",
      "coef": 1.0
     },
     {
      "var": "steaks eaten",
      "coef": -2.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "at least 10 steaks",
    "terms": [
